SELECT * FROM bank_loan_dataSELECT COUNT(id) AS Total_Loan_Applications FROM bank_loan_dataSELECT COUNT(id) AS PMTD_Total_Loan_Applications FROM bank_loan_dataWHERE MONTH(issue_date) = 11 AND YEAR(issue_date) = 2021SELECT SUM(loan_amount) AS Total_Funded_Amount FROM bank_loan_dataWHERE MONTH(issue_date) = 12 AND YEAR(issue_date) = 2021SELECT SUM(loan_amount) AS PMTD_Total_Funded_Amount FROM bank_loan_dataWHERE MONTH(issue_date) = 11 AND YEAR(issue_date) = 2021SELECT SUM(total_payment) AS PMTD_Total_Amount_received FROM bank_loan_dataWHERE MONTH( issue_date) = 12 AND YEAR(issue_date) =2021SELECT	ROUND(AVG(int_rate), 4) * 100 AS PMTD_Avg_Interest_Rate FROM bank_loan_data WHERE MONTH(issue_date) = 11 AND YEAR(issue_date) = 2021SELECT ROUND(AVG(dti),4) *100 AS PMTD_Avg_DTI FROM bank_loan_dataWHERE MONTH(issue_date) = 11 AND YEAR(issue_date) = 2021